//! policy requires one), TLS, and a small HTTP/1.1 exchange that behaves like `Net::HTTP`.
//! Each client keeps its own policy; none of them uses a proxy.

pub mod guard;
pub mod http;

use std::future::Future;
use std::io;
use std::net::{IpAddr, SocketAddr};
use std::pin::Pin;
