    fn inflater(&self) -> Option<Inflater> {
        if !self.decode_content || self.headers.contains_key("content-range") {
            return None;
        }
        match self.header("content-encoding")?.to_ascii_lowercase().as_str() {
            "gzip" | "x-gzip" | "deflate" => Some(Inflater::new()),
            _ => None,
