        let response = send(net, &url, ip, method.clone()).await?;
        if (300..400).contains(&response.status) {
            (url, ip) = resolve_redirect(net, response.header("location")).await?;
        } else {
            return Ok(response);
        }
    }
    Err(FetchError::TooManyRedirects)
