        // The Rails schema says `password_digest` is NOT NULL; bots (and any digest-less
        // user) store "" instead of NULL, which never authenticates (see `authenticate`).
        let password_digest = attributes.password_digest.map(PasswordDigest::into_string).unwrap_or_default();
