/// A mention as Rails 7 signed it: a Marshal-serialized GlobalID. Its signature no longer verifies,
/// which Campfire deliberately tolerates for users.
fn marshal_era_mention(user: i64) -> String {
    let gid = format!("gid://campfire/User/{user}");
    // Marshal.dump of a UTF-8 String: version, ivar, string with a small-int length, then E: true.
    let mut marshal = vec![4, 8, b'I', b'"', gid.len() as u8 + 5];
    marshal.extend_from_slice(gid.as_bytes());
    marshal.extend_from_slice(&[6, b':', 6, b'E', b'T']);
    let data = rails_compat::encoding::strict_encode(&marshal);
    let envelope = format!(r#"{{"_rails":{{"message":"{data}","exp":null,"pur":"attachable"}}}}"#);
    format!(
        r#"<action-text-attachment sgid="{}--0123456789abcdef0123456789abcdef01234567" content-type="application/vnd.campfire.mention"></action-text-attachment>"#,
        rails_compat::encoding::strict_encode(envelope.as_bytes())
    )
}

