fn opengraph_embed(href: &str, title: &str, description: &str, image: &str) -> String {
    let escape = ruby_compat::erb::html_escape;
    let content = format!(
        r#"<actiontext-opengraph-embed><div class="og-embed gap "> <div class="og-embed__content"><div class="og-embed__title"><a href="{href}" rel="noreferrer" target="_blank">{}</a></div> <div class="og-embed__description">{}</div></div><div class="og-embed__image"><img src="{image}" class="image center" alt="" /></div></div></actiontext-opengraph-embed>"#,
        escape(title),
        escape(description)
    );
    format!(
        r#"<action-text-attachment content-type="application/vnd.actiontext.opengraph-embed" content="{}"></action-text-attachment>"#,
        escape(&content)
    )
}
