}

impl DbResolver<'_> {
    fn mention_user(&self, user: &User) -> MentionUser {
        MentionUser {
            id: user.id,
            name: user.name.clone(),
            title: user.title(),
            attachable_sgid: global_id::attachable_sgid(self.secrets, &GlobalId::new("User", user.id)),
